SELECT MAX(tx.transferred_at)
FROM transactions tx
JOIN transfers t ON t.transfer_id = tx.transfer_id
WHERE t.user_id = #{userId, jdbcType=CHAR}
  AND tx.recipient_id = #{recipientId, jdbcType=CHAR}
  AND tx.status = 'SUCCESS'

SELECT COUNT(1)
FROM transfers
WHERE user_id = #{userId, jdbcType=CHAR}
  AND recipient_id = #{recipientId, jdbcType=CHAR}
  AND created_at >= CURRENT_TIMESTAMP - INTERVAL 30 MINUTE
  AND status NOT IN ('CANCELLED', 'EXPIRED')

