UPDATE transfers
SET status = 'HELD', current_step = 'RISK_CHECK'
WHERE user_id = #{userId, jdbcType=CHAR}
  AND transfer_id = #{transferId, jdbcType=CHAR}
  AND status IN ('DRAFT', 'RECONFIRM', 'CONFIRMED', 'HELD')
